// Closure: makeCounter returns a function that
// keeps a private 'count' alive after makeCounter returns.
function makeCounter() {
  let count = 0;                 // private state
  return () => ++count;          // closes over count
}
const next = makeCounter();
next(); // 1
next(); // 2  -> the same count persists, unreachable from outside

class Timer {
