const app = document.getElementById("app");
async function loadClasses() {
  app.textContent = "Loading…";                 // loading state
  try {
    const res = await fetch("/classes");
    if (!res.ok) throw new Error("HTTP " + res.status);
    const { classes } = await res.json();
    render(classes);                             // success
  } catch (e) {
    app.textContent = "Couldn't load classes. Retry?"; // error state
  }
}
function render(classes) {
  app.innerHTML = "";                            // build with textContent, no XSS
  for (const c of classes) {
    const li = document.createElement("li");
    li.textContent = `${c.title} — ${c.spotsLeft} spots left`;
    app.append(li);
  }
}

// Atomic: insert only if the class still has space, in one statement.
app.post("/classes/:id/bookings", async (req, res) => {
  const { name, email } = req.body;
  if (!name || !email) return res.status(400).json({ error: "name and email required" });
  try {
    const result = await pool.query(
      `INSERT INTO bookings (class_id, name, email)
       SELECT $1, $2, $3
       WHERE (SELECT COUNT(*) FROM bookings WHERE class_id = $1)
             < (SELECT capacity FROM classes WHERE id = $1)
       RETURNING *`,
      [req.params.id, name, email]
    );
    if (result.rowCount === 0)
      return res.status(409).json({ error: "This class is fully booked." });
    res.status(201).json(result.rows[0]);
  } catch (e) {
    res.status(500).json({ error: "Could not create booking" });
  }
});

